CREATE TABLE IF NOT EXISTS p10_social_chats (id BIGINT NOT NULL AUTO_INCREMENT, sender_id BIGINT NOT NULL, receiver_id BIGINT NOT NULL, chat_type INT NOT NULL, content VARCHAR(160) NOT NULL, created_at BIGINT NOT NULL, sender_info LONGBLOB NOT NULL, receiver_name VARCHAR(128) NOT NULL, PRIMARY KEY (id), INDEX(sender_id), INDEX(receiver_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
